// Banque de fiches : compréhension et inférences (cadre TACIT).
// Chaque fiche : texte en paragraphes numérotés, puis deux séances (A et B) décrites écran par écran.
// Questions : cat (catégorie), q (énoncé), o (3 réponses), ok (indice de la bonne réponse),
// fb (retour si juste), no (retours si faux : [diagnostic, message]), p (paragraphes visés),
// cp1 / cp2 (coups de pouce), s (stratégie), aide (rappel de stratégie au palier 3).
// Diagnostics (vue adulte) : L littéral · I invention · C contresens · R référent · D détail.

export const STRATS = {
  S1: { nom: "Je me fais le film", def: "Je reformule ce que je lis et je mets à jour mon image mentale à chaque paragraphe." },
  S2: { nom: "Qui est qui ?", def: "Je remonte au mot remplacé, puis je vérifie en le remettant dans la phrase." },
  S3: { nom: "Texte + tête", def: "Le texte dit… Je sais… Donc… : je relie un indice du texte à ce que je sais." },
  S4: { nom: "Je repère le plan", def: "Je cherche les mots-indices et je fais le schéma du texte." },
  S5: { nom: "Je vérifie que ça tient", def: "Si quelque chose cloche, je m’arrête, je relis et je garde la question en tête." },
  S6: { nom: "Le texte permet-il de répondre ?", def: "Je distingue ce qui est écrit, ce qui se déduit, et ce qui n’est pas dans le texte." },
};

